select * from customer;
-- total revenue generated by male and female
select gender,sum(purchase_amount) as revenue from customer group by gender;
-- which customer used a discount but still spent more than the average purchase amount
select * from customer where discount_applied='Yes' and purchase_amount>(select avg(purchase_amount) from customer);
-- which are the top 5 products with the highest average review rating
select item_purchased,avg(review_rating) as avg_review from customer group by item_purchased order by avg(review_rating) desc limit 5;
-- compare the average purchase amount between standard and express shipping
select shipping_type,round(avg(purchase_amount),2) as avergae_amount from customer 
where shipping_type in('Express','Standard') group by shipping_type;
-- do subscribe customers spend more? compare average spend and total revenue between subscribers and non-subscribers
select subscription_status,count(customer_id) as count_customer,round(avg(purchase_amount),2) as averagepurchase,sum(purchase_amount) as total_revenue from customer 
group by subscription_status;
-- which 5 products have the highest percentage of purchases with discounts applied?
SELECT
    item_purchased,
    ROUND(
        SUM(CASE
                WHEN discount_applied = 'Yes' THEN 1
                ELSE 0
            END) * 100.0 / COUNT(*),
        2
    ) AS discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;
-- segment customers into new,returning,and loyal based on their total number of previous purchases and show the count of each segment
select case 
when previous_purchases =1 then 'new'
when previous_purchases between 2 and 10 then 'returning'
else 'loyal' end as category_customer ,count(*) as customer_in_each from customer group by category_customer;
-- top 3 most purchased products within each category
with item as (
select category,item_purchased,count(customer_id) as total_customers,row_number() over(
partition by category order by count(customer_id) desc ) as item_rank from customer group by category,item_purchased)
select item_rank,category,item_purchased ,total_customers from item where item_rank<=3;
-- are customers who are repeat buyers(more than 5 previous_purchases) also likely to subscribe?
select subscription_status,count(*) as n_customers from customer where previous_purchases>=5 group by subscription_status;
-- what is the revenue contribution of each age group 
select age_group,sum(purchase_amount) as revenue from customer group by age_group order by revenue desc;
